        &lt;&lt;Interfaccia&gt;&gt;
        + visit(Cerchio c)
        + visit(Rettangolo r)
    }

    class Element{
        &lt;&lt;Interfaccia&gt;&gt;
        + void accept(Visitor v)
    }

